const GLOSSARY_CATS = {"bean":"دانه و فرآوری","roast":"برشته‌کاری","brew":"دم‌آوری و استخراج","esp":"اسپرسو","milk":"شیر و لاته‌آرت","taste":"طعم و حس","gear":"تجهیزات","serve":"نوشیدنی‌ها و فرهنگ","farm":"ارقام و مزرعه","market":"بازار و تجارت","slang":"اصطلاح باریستا"};
const GLOSSARY = [{"en":"Arabica","fa":"عربیکا","cat":"bean","d":"Coffea arabica حدود ۶۰٪ تولید جهان را تشکیل می‌دهد؛ معمولاً در ارتفاع ۱٬۲۰۰ تا ۱٬۵۰۰ متر کشت می‌شود (از سطح دریا تا ۲٬۸۰۰ متر هم گزارش شده). قهوه‌های گورمه تقریباً همه از ارقام ملایم عربیکا هستند. دانه‌ی عربیکای معمولی حدود ۱۲ میلی‌گرم کافئین در هر گرم ماده‌ی خشک دارد.","s":[["Wikipedia — Coffea arabica","https://en.wikipedia.org/wiki/Coffea_arabica"]]},{"en":"Robusta","fa":"روبوستا","cat":"bean","d":"Coffea canephora حدود ۴۵٪ تولید جهان است؛ کافئین آن ۲٫۷٪ در برابر ۱٫۵٪ عربیکا، با اسیدیته‌ی کمتر و تلخی بیشتر. در برابر آفت مقاوم‌تر و تولیدش ارزان‌تر است. بیشتر آن قهوه‌ی فوری می‌شود و روبوستای خوب در ترکیب‌های سنتی اسپرسوی ایتالیایی به بدنه و کرما کمک می‌کند.","s":[["Wikipedia — Coffea canephora","https://en.wikipedia.org/wiki/Coffea_canephora"]]},{"en":"Single Origin","fa":"تک‌خاستگاه","cat":"bean","d":"قهوه‌ای که در یک خاستگاه جغرافیایی مشخص کشت شده است.","s":[["Wikipedia — Single-origin coffee","https://en.wikipedia.org/wiki/Single-origin_coffee"]]},{"en":"Blend","fa":"بلند (ترکیب)","cat":"bean","d":"قهوه‌ای که از ترکیب خاستگاه‌های مختلف ساخته می‌شود، در برابر قهوه‌ی تک‌خاستگاه.","s":[["Wikipedia — Single-origin coffee","https://en.wikipedia.org/wiki/Single-origin_coffee"]]},{"en":"Green Coffee","fa":"قهوه‌ی سبز","cat":"bean","d":"دانه‌ی برشته‌نشده‌ی قهوه که پس از حذف پوست و موسیلاژ، لایه‌ی مومی بیرونی خود را نگه می‌دارد. می‌تواند چند سال قابل‌استفاده بماند ولی با شرایط نگهداری کیفیتش افت می‌کند؛ بعضی قهوه‌ها ۱۴ تا ۱۶ ماه ویژگی‌شان را حفظ می‌کنند.","s":[["Wikipedia — Coffee bean","https://en.wikipedia.org/wiki/Coffee_bean"],["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"]]},{"en":"Cherry","fa":"چری (میوه‌ی قهوه)","cat":"bean","d":"میوه‌ی گیاه قهوه که حدود هشت ماه پس از گل‌دهی می‌رسد و از سبز به قرمز تغییر رنگ می‌دهد؛ معمولاً دو دانه با سطح‌های تخت رو به هم دارد.","s":[["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"],["Wikipedia — Coffee bean","https://en.wikipedia.org/wiki/Coffee_bean"]]},{"en":"Peaberry","fa":"پی‌بری","cat":"bean","d":"یک دانه‌ی گرد تک‌هسته‌ای که به‌جای جفت معمول در میوه شکل می‌گیرد؛ وقتی فقط یکی از دو دانه بارور شود و چیزی آن را صاف نکند. معمولاً حدود ۵٪ دانه‌های برداشت‌شده است (در صفحه‌ی Coffee bean ۱۰ تا ۱۵٪ آمده؛ منابع با هم یکسان نیستند).","s":[["Wikipedia — Peaberry","https://en.wikipedia.org/wiki/Peaberry"],["Wikipedia — Coffee bean","https://en.wikipedia.org/wiki/Coffee_bean"]]},{"en":"Variety vs Cultivar","fa":"واریته در برابر کولتیوار","cat":"farm","d":"طبق تعریف SCAA: واریته بیشتر ویژگی‌های گونه را حفظ می‌کند ولی در چیزی تفاوت دارد؛ کولتیوار هر واریته‌ای است که با فن‌های کشاورزی پدید آمده و معمولاً در جمعیت‌های طبیعی دیده نمی‌شود.","s":[["Wikipedia — List of coffee varieties","https://en.wikipedia.org/wiki/List_of_coffee_varieties"]]},{"en":"Typica","fa":"تیپیکا","cat":"farm","d":"از ذخیره‌ی یمنی می‌آید که ابتدا به مالابار هند برده شد و سپس به اندونزی، فیلیپین و هند غربی رسید؛ چند واریته‌ی دیگر از آن مشتق شده‌اند.","s":[["Wikipedia — List of coffee varieties","https://en.wikipedia.org/wiki/List_of_coffee_varieties"]]},{"en":"Bourbon","fa":"بوربن","cat":"farm","d":"در رئونیون، رواندا و آمریکای لاتین کشت می‌شود و ۲۰ تا ۳۰٪ میوه‌ی بیشتر از رقم‌های تیپیکا تولید می‌کند.","s":[["Wikipedia — List of coffee varieties","https://en.wikipedia.org/wiki/List_of_coffee_varieties"]]},{"en":"Caturra","fa":"کاتورا","cat":"farm","d":"جهشی طبیعی از بوربن قرمز؛ چون بوته کوتاه‌تر است بازده بیشتری دارد، زودتر می‌رسد و در برابر بیماری مقاوم‌تر است، ولی به‌دلیل بازده بالا کیفیت فنجانش ضعیف‌تر است.","s":[["Wikipedia — List of coffee varieties","https://en.wikipedia.org/wiki/List_of_coffee_varieties"]]},{"en":"Geisha / Gesha","fa":"گیشا","cat":"farm","d":"اصالتاً از روستای گشا در اتیوپی؛ در دهه‌ی ۱۹۵۰ به‌عنوان رقم مقاوم به زنگ کاشته و در اوایل دهه‌ی ۲۰۰۰ دوباره کشف شد. در مزایده‌ها بسیار گران است؛ رکورد ۸۰۳ دلار برای هر پوند گیشای طبیعی در ۲۰۱۸.","s":[["Wikipedia — List of coffee varieties","https://en.wikipedia.org/wiki/List_of_coffee_varieties"]]},{"en":"Altitude","fa":"ارتفاع کشت","cat":"farm","d":"عربیکا معمولاً در ارتفاع ۱٬۲۰۰ تا ۱٬۵۰۰ متر کشت می‌شود و ارتفاع کشت از معیارهای درجه‌بندی قهوه است.","s":[["Wikipedia — Coffea arabica","https://en.wikipedia.org/wiki/Coffea_arabica"],["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"]]},{"en":"Washed (Wet) Process","fa":"فرآوری شسته (مرطوب)","cat":"bean","d":"روشی که در آن میوه‌ی پوشاننده‌ی دانه پیش از خشک شدن برداشته می‌شود. طبق مرکز تجارت بین‌المللی رایج‌ترین روش و اغلب باکیفیت‌ترین است ولی مهارت و آب زیاد می‌خواهد.","s":[["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"]]},{"en":"Natural (Dry) Process","fa":"فرآوری طبیعی (خشک)","cat":"bean","d":"قدیمی‌ترین روش: میوه‌ی کامل پس از برداشت تمیز و زیر آفتاب (روی میز یا پاتیو) خشک می‌شود.","s":[["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"]]},{"en":"Honey Process","fa":"فرآوری عسلی","cat":"bean","d":"روش نیمه‌خشک: پوست بیرونی برداشته می‌شود ولی موسیلاژ روی پوسته‌ی چرمی می‌ماند و دانه تخمیر و خشک می‌شود، بدون مرحله‌ی شستن. بسته به مقدار موسیلاژ زرد، قرمز یا سیاه نامیده می‌شود و آب بسیار کمتری از روش مرطوب مصرف می‌کند.","s":[["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"]]},{"en":"Specialty Coffee","fa":"قهوه‌ی اسپشیالتی","cat":"bean","d":"قهوه‌ای که در فرم کاپینگ SCA امتیاز ۸۰ یا بیشتر می‌گیرد.","s":[["Wikipedia — Specialty coffee","https://en.wikipedia.org/wiki/Specialty_coffee"],["Wikipedia — Specialty Coffee Association","https://en.wikipedia.org/wiki/Specialty_Coffee_Association"]]},{"en":"Cupping","fa":"کاپینگ","cat":"taste","d":"تمرین بررسی طعم و بوی قهوه‌ی دم‌شده: بوییدن عمیق و مکیدن قهوه از قاشق تا هوا بخورد و روی زبان پخش شود. بدنه، شیرینی، اسیدیته، طعم و پس‌مزه ارزیابی می‌شود.","s":[["Wikipedia — Coffee cupping","https://en.wikipedia.org/wiki/Coffee_cupping"]]},{"en":"Fair Trade","fa":"فیر تریید","cat":"market","d":"قهوه‌ای که طبق استانداردهای تجارت منصفانه توسط سازمان‌های مربوط گواهی شده باشد. «دایرکت تریید» مدلی بدون گواهی شخص ثالث است که کنترل بیشتری بر کیفیت و توانمندسازی کشاورز می‌دهد.","s":[["Wikipedia — Fair trade coffee","https://en.wikipedia.org/wiki/Fair_trade_coffee"]]},{"en":"Third Wave","fa":"موج سوم","cat":"market","d":"نگاهی که قهوه را محصول مزرعه‌ای با خاستگاه مشخص و برشته‌ی سبک می‌بیند تا ویژگی‌های هر دانه نمایان شود. موج اول بر قیمت پایین و طعم یکنواخت (قهوه‌ی آسیاب‌شده‌ی قوطی‌ای) تمرکز داشت و موج دوم مفهوم کشورهای خاستگاه و اسپرسوی ایتالیایی را رواج داد.","s":[["Wikipedia — Third wave of coffee","https://en.wikipedia.org/wiki/Third_wave_of_coffee"]]},{"en":"SCA","fa":"انجمن قهوه‌ی اسپشیالتی","cat":"market","d":"سازمان تجاری غیرانتفاعی صنعت قهوه‌ی اسپشیالتی؛ SCAA در ۱۹۸۲ تأسیس شد و در ژانویه ۲۰۱۷ با SCAE ادغام شد و SCA با بیش از ۱۰٬۰۰۰ عضو فعال را ساخت.","s":[["Wikipedia — Specialty Coffee Association","https://en.wikipedia.org/wiki/Specialty_Coffee_Association"]]},{"en":"Terroir","fa":"ترووار","cat":"farm","d":"واژه‌ی فرانسوی برای عوامل محیطی (جایگاه، روش کشت و زیستگاه) که ویژگی‌های محصول را شکل می‌دهند؛ قهوه یکی از محصولات صنعتی‌ست که این مفهوم می‌تواند درباره‌اش صدق کند.","s":[["Wikipedia — Terroir","https://en.wikipedia.org/wiki/Terroir"]]},{"en":"Light Roast","fa":"برشته‌ی روشن","cat":"roast","d":"بدنه‌ی سبک‌تر، اسیدیته‌ی بیشتر و بدون طعم برشته‌ی آشکار؛ دمای داخلی حدود ۱۹۶ تا ۲۰۵ درجه.","s":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"en":"Medium Roast","fa":"برشته‌ی متوسط","cat":"roast","d":"قندها بیشتر کاراملی شده‌اند و اسیدیته کم‌رنگ شده؛ دمای داخلی حدود ۲۱۰ تا ۲۱۹ درجه.","s":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"en":"Dark Roast","fa":"برشته‌ی تیره","cat":"roast","d":"بدنه‌ی پر و طعم تلخ‌شیرین پررنگ می‌شود و عطر و طعم برشته آشکار است؛ دمای داخلی حدود ۲۲۵ تا ۲۴۵ درجه. بیشتر روغن روی سطح دانه می‌آید و هرچه از کرک دوم دورتر شود بیشتر دیده می‌شود.","s":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"en":"Roast Level Names","fa":"نام درجه‌های برشته‌کاری","cat":"roast","d":"برشته‌کارها از نام‌هایی مثل سیتی (City)، فول سیتی، وین، فرنچ و ایتالیایی برای درجه‌های برشته استفاده می‌کنند که هرکدام به دمای داخلی مشخصی گره خورده است؛ تعریف دقیقشان بین برشته‌کارها یکسان نیست.","s":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"en":"First Crack","fa":"کرک اول","cat":"roast","d":"حدود ۱۹۶ درجه‌ی سانتی‌گراد دانه‌ها صدای ترقه می‌دهند؛ آغاز برشته‌ی بسیار روشن.","s":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"en":"Second Crack","fa":"کرک دوم","cat":"roast","d":"حدود ۲۲۴ درجه دانه‌ها بار دیگر ترقه می‌دهند.","s":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"en":"Maillard Reaction","fa":"واکنش میلارد","cat":"roast","d":"دانه‌ی خام قهوه طعم برشته ندارد؛ طعم برشته به‌خاطر واکنش میلارد و واکنش‌های شیمیایی دیگر هنگام برشته‌کاری پدید می‌آید.","s":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"en":"Degassing","fa":"گازگیری","cat":"roast","d":"قهوه‌ی برشته CO₂ آزاد می‌کند؛ قهوه‌ای که قرار است وکیوم شود باید پیش از بسته‌بندی چند روز گاز بدهد.","s":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"en":"Drum Roaster","fa":"رُستر درام","cat":"roast","d":"دستگاه برشته‌کاری با درام افقی چرخان که دانه‌ها را در محیط گرم می‌غلتاند؛ رایج‌ترین نوع با گرمایش غیرمستقیم از زیر درام است.","s":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"en":"Extraction","fa":"استخراج","cat":"brew","d":"درصدی (از نظر وزن) از پودر قهوه که در آب حل می‌شود؛ «بازده محلول‌ها» هم نامیده می‌شود.","s":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"en":"Over-extraction","fa":"استخراج بیش‌ازحد","cat":"brew","d":"نتیجه‌ی ماندن طولانی قهوه روی تفاله یا آسیاب بسیار ریز؛ تلخی و طعم تند.","s":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"],["Wikipedia — French press","https://en.wikipedia.org/wiki/French_press"]]},{"en":"TDS","fa":"مواد جامد محلول (TDS)","cat":"brew","d":"سنجه‌ی میزان غلظت یا رقیق‌بودن قهوه (Total Dissolved Solids).","s":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"en":"Brew Ratio","fa":"نسبت دم‌آوری","cat":"brew","d":"نسبت جرم پودر قهوه به حجم آب. نسبت ۱۵ تا ۱۸ به ۱ (جرمی) ترجیح داده می‌شود و استانداردها حدود ۵۵ گرم در لیتر (آمریکایی) تا ۶۳ گرم در لیتر (نروژی)‌اند.","s":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"en":"Grind Size","fa":"اندازه‌ی آسیاب","cat":"brew","d":"ریزی پودر روی دم‌آوری اثر شدیدی دارد؛ روش‌های طولانی‌تر به آسیاب درشت‌تری نیاز دارند.","s":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"en":"Bloom","fa":"بلوم (پیش‌خیس)","cat":"brew","d":"خیساندن اولیه‌ی پودر با کمی آب داغ حدود ۳۰ تا ۴۵ ثانیه که CO₂ را به‌صورت حباب یا کف آزاد می‌کند و طبق منبع طعم را بهتر می‌کند.","s":[["Wikipedia — Pour-over coffee","https://en.wikipedia.org/wiki/Pour-over_coffee"]]},{"en":"Pour-over","fa":"پوراوور","cat":"brew","d":"دم‌آوری قطره‌ای دستی: آب روی بستر پودر در محفظه‌ای با فیلتر ریخته می‌شود.","s":[["Wikipedia — Pour-over coffee","https://en.wikipedia.org/wiki/Pour-over_coffee"]]},{"en":"Drip Brew","fa":"قهوه‌ی قطره‌ای (فیلتری)","cat":"brew","d":"قهوه‌ای که با چکیدن آب داغ روی پودر ساخته می‌شود؛ آب از فیلتری که پودر را نگه می‌دارد می‌گذرد.","s":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"en":"Immersion","fa":"غوطه‌وری","cat":"brew","d":"روشی که پودر در آب خیسانده می‌شود، مثل فرنچ‌پرس.","s":[["Wikipedia — French press","https://en.wikipedia.org/wiki/French_press"],["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"en":"Dose","fa":"دوز","cat":"esp","d":"استاندارد مؤسسه‌ی ملی اسپرسوی ایتالیا ۷ گرم با تلورانس نیم‌گرم (از ۶٫۵ تا ۷٫۵ گرم) پودر برای یک شات؛ شات‌های یک‌تایی، دوتایی و سه‌تایی تقریباً ۷، ۱۴ و ۲۱ گرم.","s":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"en":"Yield","fa":"حجم / وزن خروجی","cat":"esp","d":"استاندارد ایتالیایی حجم فنجان (با کرما) ۲۵ میلی‌لیتر با تلورانس ۲٫۵ میلی‌لیتر (از ۲۲٫۵ تا ۲۷٫۵) است؛ چون کرما مقایسه‌ی حجمی را دشوار می‌کند، برای سنجش دقیق از جرم نوشیدنی استفاده می‌شود.","s":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"en":"Espresso","fa":"اسپرسو","cat":"esp","d":"قهوه‌ای که آب داغ (حدود ۹۱ تا ۹۵ درجه) آن را با فشار ۸ تا ۱۸ بار از «پاک» (بستر فشرده‌ی پودر) می‌گذراند. زمان معمول عصاره‌گیری ۲۵ تا ۳۰ ثانیه است؛ حدود ۷ گرم قهوه برای شات ۲۵ میلی‌لیتری.","s":[["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"],["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"en":"Pulling a Shot","fa":"کشیدن شات","cat":"slang","d":"ساخت اسپرسو؛ از ماشین‌های اهرمی می‌آید که باریستا دسته را پایین می‌کشید.","s":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"en":"Crema","fa":"کرما","cat":"esp","d":"لایه‌ی کف متراکم روی اسپرسو که مخصوص اسپرسوست؛ وقتی آب تحت فشار بسیار بالا CO₂ حاصل از برشته‌کاری را بیشتر حل کند پدید می‌آید.","s":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"en":"Portafilter","fa":"پورتافیلتر","cat":"esp","d":"دسته‌ای (group handle) که به گروه‌هد ماشین‌های نیمه‌خودکار و پیستونی وصل می‌شود.","s":[["Wikipedia — Espresso machine","https://en.wikipedia.org/wiki/Espresso_machine"]]},{"en":"Group Head","fa":"گروه‌هد","cat":"esp","d":"محل نصب پورتافیلتر قابل‌جداشدن روی ماشین اسپرسو.","s":[["Wikipedia — Espresso machine","https://en.wikipedia.org/wiki/Espresso_machine"]]},{"en":"Tamping","fa":"تمپ","cat":"esp","d":"فشردن و هموار کردن پودر قهوه؛ نفوذ یکنواخت آب در پودر را بهتر می‌کند.","s":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"en":"Steam Wand","fa":"لوله‌ی بخار","cat":"milk","d":"ابزار کمکی ماشین اسپرسو برای بخار دادن و کف‌کردن شیر.","s":[["Wikipedia — Espresso machine","https://en.wikipedia.org/wiki/Espresso_machine"]]},{"en":"Cooling Flush","fa":"فلاش خنک‌کننده","cat":"esp","d":"در ماشین‌های مبدل حرارتی پیش از اولین کشیدن اسپرسو یک فلاش خنک‌کننده‌ی ۴ تا ۶ ثانیه‌ای لازم است.","s":[["Wikipedia — Espresso machine","https://en.wikipedia.org/wiki/Espresso_machine"]]},{"en":"Ristretto","fa":"ریسترتو","cat":"esp","d":"شات «کوتاه»: همان مقدار قهوه‌ی شات دوتایی (حدود ۱۴ تا ۱۸ گرم) با نصف آب، حدود ۲۰ میلی‌لیتر؛ غلیظ‌تر با بدنه‌ی بیشتر و تلخی کمتر.","s":[["Wikipedia — Ristretto","https://en.wikipedia.org/wiki/Ristretto"],["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"en":"Lungo","fa":"لونگو","cat":"esp","d":"شات «بلند» (café allongé در فرانسوی): یک شات اسپرسو با آب بیشتر، معمولاً حدود دو برابر؛ حدود ۵۰ تا ۷۰ میلی‌لیتر. نسبت‌های تقریبی ریسترتو ۱:۱، نورمال ۱:۲ و لونگو ۱:۴ است و این نام‌ها اندازه‌ی دقیق ندارند.","s":[["Wikipedia — Lungo","https://en.wikipedia.org/wiki/Lungo"],["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"en":"Doppio / Solo / Triplo","fa":"دوپیو / سولو / تریپلو","cat":"slang","d":"اندازه‌های اسپرسو: دوتایی، یک‌تایی و سه‌تایی؛ در اسپرسوی آمریکایی «تریپل» و «کواد» سه یا چهار شات‌اند.","s":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"en":"Caffè Crema","fa":"کافه کرما","cat":"esp","d":"شات بلندتر ۱۲۰ تا ۲۴۰ میلی‌لیتر که با آسیاب درشت‌تر دم می‌شود.","s":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"en":"Steaming","fa":"بخار دادن شیر","cat":"milk","d":"بخار دادن وقتی تمام می‌شود که شیر به حدود ۷۰ درجه برسد؛ بالای ۸۲ درجه شیر می‌سوزد و بافت آن خراب می‌شود چون کازئین دناتوره می‌شود.","s":[["Wikipedia — Microfoam","https://en.wikipedia.org/wiki/Microfoam"]]},{"en":"Microfoam","fa":"میکروفوم","cat":"milk","d":"کف براق و کمی غلیظ با حباب‌های ریز و یکنواخت، شبیه رنگ خیس یا مارشمالوی ذوب‌شده؛ با ماکروفوم (کف درشت) تفاوت دارد.","s":[["Wikipedia — Microfoam","https://en.wikipedia.org/wiki/Microfoam"]]},{"en":"Latte Art","fa":"لاته‌آرت","cat":"milk","d":"روش ساخت قهوه با ریختن میکروفوم روی شات اسپرسو؛ نیازمند اسپرسوی دارای کرما و میکروفوم است. طرح می‌تواند حین ریختن یا بعداً با چوب کشیده شود (etching). در آمریکا در سیاتل دهه‌های ۱۹۸۰ و ۱۹۹۰ شکل گرفت.","s":[["Wikipedia — Latte art","https://en.wikipedia.org/wiki/Latte_art"]]},{"en":"Barista","fa":"باریستا","cat":"milk","d":"فردی که اسپرسو را آماده و «می‌کشد»؛ نوشیدنی‌های دیگر مهارت بیشتری در بخار دادن، ریختن و لاته‌آرت می‌خواهند.","s":[["Wikipedia — Barista","https://en.wikipedia.org/wiki/Barista"]]},{"en":"Sour","fa":"ترشی (Sour)","cat":"taste","d":"طعم بنیادی مرتبط با محلول اسید سیتریک (واژه‌نامه‌ی حسی WCR). در این واژه‌نامه «اسیدیته» به‌عنوان مدخل جدا نیامده است.","s":[["World Coffee Research — Sensory Lexicon (2nd ed., 2017)","https://worldcoffeeresearch.org/download/5806d8c7-cd7c-4882-a81a-2850bd6fbd36"]]},{"en":"Bitter","fa":"تلخی (Bitter)","cat":"taste","d":"طعم بنیادی مرتبط با محلول کافئین.","s":[["World Coffee Research — Sensory Lexicon (2nd ed., 2017)","https://worldcoffeeresearch.org/download/5806d8c7-cd7c-4882-a81a-2850bd6fbd36"]]},{"en":"Sweet","fa":"شیرینی (Sweet)","cat":"taste","d":"طعم بنیادی که ساکارز نمونه‌ی آن است.","s":[["World Coffee Research — Sensory Lexicon (2nd ed., 2017)","https://worldcoffeeresearch.org/download/5806d8c7-cd7c-4882-a81a-2850bd6fbd36"]]},{"en":"Fullness","fa":"پری (Fullness)","cat":"taste","d":"«بنیان نت‌های طعمی که به نوشیدنی جوهر می‌دهد» (در بخش Amplitude؛ نزدیک‌ترین مفهوم به «بدنه»).","s":[["World Coffee Research — Sensory Lexicon (2nd ed., 2017)","https://worldcoffeeresearch.org/download/5806d8c7-cd7c-4882-a81a-2850bd6fbd36"]]},{"en":"Mouthfeel","fa":"حس دهان","cat":"taste","d":"احساس‌های فیزیکی در دهان که غذا یا نوشیدنی ایجاد می‌کند و از طعم جداست. بخش حس دهان در Sensory Lexicon شامل مدخل‌های Mouth Drying، Thickness، Metallic و Oily است.","s":[["Wikipedia — Mouthfeel","https://en.wikipedia.org/wiki/Mouthfeel"],["World Coffee Research — Sensory Lexicon (2nd ed., 2017)","https://worldcoffeeresearch.org/download/5806d8c7-cd7c-4882-a81a-2850bd6fbd36"]]},{"en":"Astringency","fa":"گس‌بودن","cat":"taste","d":"حس خشک و چروک‌کننده یا بی‌حس‌کننده‌ی ناشی از تانن‌ها (پلی‌فنول‌هایی که با پروتئین‌های بزاق کلوخه می‌شوند).","s":[["Wikipedia — Astringent","https://en.wikipedia.org/wiki/Astringent"]]},{"en":"Longevity","fa":"ماندگاری","cat":"taste","d":"مدت پایداری تجربه‌ی حسی در دهان و پس از قورت دادن؛ نزدیک‌ترین مفهوم به پس‌مزه در WCR. اندازه‌گیری پس‌مزه در روش آن ۱۵ ثانیه انتظار است.","s":[["World Coffee Research — Sensory Lexicon (2nd ed., 2017)","https://worldcoffeeresearch.org/download/5806d8c7-cd7c-4882-a81a-2850bd6fbd36"]]},{"en":"Aftertaste","fa":"پس‌مزه","cat":"taste","d":"پس‌مزه می‌تواند با غذایی که پس از آن می‌آید فرق کند. بو یکی از چند عامل تعیین‌کننده‌ی طعم است، کنار مزه، بافت و دما.","s":[["Wikipedia — Taste","https://en.wikipedia.org/wiki/Taste"]]},{"en":"Floral","fa":"گلی (Floral)","cat":"taste","d":"عطری شیرین، سبک و کمی خوش‌بو مرتبط با گل‌های تازه.","s":[["World Coffee Research — Sensory Lexicon (2nd ed., 2017)","https://worldcoffeeresearch.org/download/5806d8c7-cd7c-4882-a81a-2850bd6fbd36"]]},{"en":"Fruity","fa":"میوه‌ای (Fruity)","cat":"taste","d":"ترکیب عطری شیرین و گلی از میوه‌های رسیده‌ی گوناگون.","s":[["World Coffee Research — Sensory Lexicon (2nd ed., 2017)","https://worldcoffeeresearch.org/download/5806d8c7-cd7c-4882-a81a-2850bd6fbd36"]]},{"en":"Roasted","fa":"برشته (Roasted)","cat":"taste","d":"تأثیر قهوه‌ای تیره‌ی محصولاتی که با گرمای خشک زیاد پخته شده‌اند؛ شامل نت‌های تلخ یا سوخته نمی‌شود.","s":[["World Coffee Research — Sensory Lexicon (2nd ed., 2017)","https://worldcoffeeresearch.org/download/5806d8c7-cd7c-4882-a81a-2850bd6fbd36"]]},{"en":"Nutty","fa":"آجیلی (Nutty)","cat":"taste","d":"عطری کمی شیرین، قهوه‌ای، چوبی، روغنی، کپک‌دار، گس و تلخ که با آجیل، تخمه، حبوبات و غلات مرتبط است.","s":[["World Coffee Research — Sensory Lexicon (2nd ed., 2017)","https://worldcoffeeresearch.org/download/5806d8c7-cd7c-4882-a81a-2850bd6fbd36"]]},{"en":"Cocoa","fa":"کاکائویی (Cocoa)","cat":"taste","d":"عطری قهوه‌ای، شیرین، گردآلود و کپکی، اغلب تلخ، مرتبط با دانه‌ی کاکائو، پودر کاکائو و شکلات.","s":[["World Coffee Research — Sensory Lexicon (2nd ed., 2017)","https://worldcoffeeresearch.org/download/5806d8c7-cd7c-4882-a81a-2850bd6fbd36"]]},{"en":"Brown Spice","fa":"ادویه‌ی قهوه‌ای","cat":"taste","d":"عطر شیرین قهوه‌ای مرتبط با ادویه‌هایی مثل دارچین، میخک، جوزهندی و ملس.","s":[["World Coffee Research — Sensory Lexicon (2nd ed., 2017)","https://worldcoffeeresearch.org/download/5806d8c7-cd7c-4882-a81a-2850bd6fbd36"]]},{"en":"Burr Grinder","fa":"آسیاب برقی تیغه‌ای ساب (Burr)","cat":"gear","d":"از دو عنصر ساینده‌ی چرخان استفاده می‌کند که دانه را خرد می‌کنند؛ گرمای اصطکاکی کمتری از آسیاب تیغه‌ای دارد و ذرات یکنواخت‌تری می‌دهد که اندازه‌شان با فاصله‌ی دو سطح تعیین می‌شود و کاربر تنظیم می‌کند.","s":[["Wikipedia — Coffee grinder","https://en.wikipedia.org/wiki/Coffee_grinder"],["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"en":"Blade Grinder","fa":"آسیاب تیغه‌ای","cat":"gear","d":"دانه را با تیغه‌هایی که با سرعت زیاد می‌چرخند خرد می‌کند و ذرات با اندازه‌های بسیار متفاوت می‌دهد.","s":[["Wikipedia — Coffee grinder","https://en.wikipedia.org/wiki/Coffee_grinder"],["Wikipedia — Coffee preparation","https://en.wikipedia.org/wiki/Coffee_preparation"]]},{"en":"Fines","fa":"فینز (ذرات ریز)","cat":"gear","d":"ذرات بسیار ریز آسیاب که می‌توانند حس دهان را تحت تأثیر قرار دهند، به‌ویژه در فرنچ‌پرس.","s":[["Wikipedia — Coffee grinder","https://en.wikipedia.org/wiki/Coffee_grinder"]]},{"en":"Cezve / Ibrik","fa":"جذوه / ابریق","cat":"gear","d":"ظرف کوچک دسته‌بلند با لبه‌ی ریزش که مخصوص قهوه‌ی ترک ساخته شده؛ سنتی از برنج یا مس و جدیدتر از استیل، آلومینیوم یا سرامیک. در ترکی «ibrik» یعنی کوزه، نه قهوه‌جوش.","s":[["Wikipedia — Cezve","https://en.wikipedia.org/wiki/Cezve"]]},{"en":"Moka Pot","fa":"موکاپات","cat":"gear","d":"نسبت جرمی قهوه به آب حدود ۱:۱۰ با ۳ تا ۴٪ جامد حل‌شده (اسپرسو ۹ تا ۱۰٪، قطره‌ای حدود ۲٪). اندازه‌ها از یک تا هجده سروینگ ۵۰ میلی‌لیتری است.","s":[["Wikipedia — Moka pot","https://en.wikipedia.org/wiki/Moka_pot"]]},{"en":"French Press","fa":"فرنچ‌پرس","cat":"gear","d":"دم‌ساز غوطه‌وری: قهوه‌ی درشت (شبیه نمک خوراکی) با آب ۹۳ تا ۹۶ درجه، حدود ۳۰ گرم برای ۵۰۰ میلی‌لیتر آب و حدود چهار دقیقه؛ پیستون با فیلتر توری فلزی یا نایلونی پودر را پایین نگه می‌دارد.","s":[["Wikipedia — French press","https://en.wikipedia.org/wiki/French_press"]]},{"en":"Americano","fa":"آمریکانو","cat":"serve","d":"یک یا دو شات اسپرسو به‌علاوه‌ی ۳۰ تا ۴۷۰ میلی‌لیتر آب داغ؛ در تعریف دقیق‌تر آب روی اسپرسو ریخته می‌شود و کرما از بین می‌رود.","s":[["Wikipedia — Caffè Americano","https://en.wikipedia.org/wiki/Caff%C3%A8_Americano"]]},{"en":"Long Black","fa":"لانگ‌بلک","cat":"serve","d":"دو شات اسپرسو روی حدود ۱۰۰ تا ۱۲۰ میلی‌لیتر آب داغ؛ کرما حفظ می‌شود و چون آب کمتر از آمریکانو است طعم قوی‌تر دارد.","s":[["Wikipedia — Long black","https://en.wikipedia.org/wiki/Long_black"]]},{"en":"Flat White","fa":"فلت وایت","cat":"serve","d":"اسپرسو و شیر بخارداده با نسبت اسپرسوی بیشتر از لاته و بدون لایه‌ی کف ضخیم کاپوچینو. مبدأ آن نامشخص است؛ استرالیا و نیوزیلند هر دو ادعا دارند.","s":[["Wikipedia — Flat white","https://en.wikipedia.org/wiki/Flat_white"]]},{"en":"Cortado","fa":"کورتادو","cat":"serve","d":"نوشیدنی اسپانیایی از اسپرسو و مقدار تقریباً برابر شیر گرم بخارداده‌ی بدون کف؛ نسبت دقیق بین مناطق فرق می‌کند.","s":[["Wikipedia — Cortado","https://en.wikipedia.org/wiki/Cortado"]]},{"en":"Macchiato","fa":"ماکیاتو","cat":"serve","d":"اسپرسو با مقدار کمی شیر که معمولاً کف‌دار است؛ «macchiato» در ایتالیایی یعنی «لک‌دار».","s":[["Wikipedia — Caffè macchiato","https://en.wikipedia.org/wiki/Caff%C3%A8_macchiato"]]},{"en":"Cappuccino","fa":"کاپوچینو","cat":"serve","d":"نوشیدنی بر پایه‌ی اسپرسو با شیر بخارداده و لایه‌ی کف شیر؛ به‌طور سنتی یک‌سوم اسپرسو، یک‌سوم شیر و یک‌سوم کف، و حجم ۱۵۰ تا ۱۸۰ میلی‌لیتر. کف آن ماکروفوم است نه میکروفوم و قوانین مسابقه‌ی جهانی باریستا حداقل ۱ سانتی‌متر عمق کف می‌خواهد.","s":[["Wikipedia — Cappuccino","https://en.wikipedia.org/wiki/Cappuccino"]]},{"en":"Affogato","fa":"آفوگاتو","cat":"serve","d":"دسر ایتالیایی از یک اسکوپ ژلاتو (وانیل یا فیورده‌لاته) با اسپرسو؛ «غرق‌شده در قهوه».","s":[["Wikipedia — Affogato","https://en.wikipedia.org/wiki/Affogato"]]},{"en":"Cold Brew","fa":"کلد برو","cat":"serve","d":"دم‌آوری بدون حرارت: قهوه‌ی درشت ۱۲ تا ۲۴ ساعت در آب ولرم خیس می‌خورد و سپس صاف می‌شود؛ غلیظ حاصل با آب یا شیر رقیق می‌شود. دم‌آوری ۲۴ ساعته در دمای پایین‌تر، در حجم برابر، کافئین بیشتری از ۶ دقیقه در ۹۸ درجه می‌دهد.","s":[["Wikipedia — Cold brew coffee","https://en.wikipedia.org/wiki/Cold_brew_coffee"],["Wikipedia — Iced coffee","https://en.wikipedia.org/wiki/Iced_coffee"]]},{"en":"Iced Coffee","fa":"قهوه‌ی سرد","cat":"serve","d":"قهوه‌ای که سرد سرو می‌شود؛ معمولاً با دم‌آوری داغ و ریختن روی یخ و با غلظت بیشتر برای جبران رقیق‌شدن، یا با دم‌آوری سرد.","s":[["Wikipedia — Iced coffee","https://en.wikipedia.org/wiki/Iced_coffee"]]},{"en":"Decaf","fa":"بدون کافئین","cat":"serve","d":"قهوه‌ای که کافئینش گرفته شده است. استاندارد FDA آمریکا حذف دست‌کم ۹۷٪ و استاندارد اتحادیه‌ی اروپا ۹۹٫۹٪ است؛ مطالعه‌ی ۲۰۰۶ نشان داد معمولاً ۱ تا ۲٪ کافئین می‌ماند و گاهی تا ۲۰٪. روش‌ها: حلال آلی مستقیم و غیرمستقیم، آب سوئیسی (۸ تا ۱۰ ساعت)، CO₂ فوق‌بحرانی و روش روغن قهوه.","s":[["Wikipedia — Decaffeination","https://en.wikipedia.org/wiki/Decaffeination"]]},{"en":"Irish Coffee","fa":"ایریش کافی","cat":"serve","d":"۵۰ میلی‌لیتر ویسکی ایرلندی، ۱۲۰ میلی‌لیتر قهوه‌ی سیاه داغ، دست‌کم یک قاشق چای‌خوری شکر و ۵۰ میلی‌لیتر خامه‌ی سرد که روی پشت قاشق ریخته می‌شود تا شناور بماند.","s":[["Wikipedia — Irish coffee","https://en.wikipedia.org/wiki/Irish_coffee"]]},{"en":"Espresso Tonic","fa":"اسپرسو تونیک","cat":"serve","d":"نوشیدنی بدون الکل از اسپرسو و آب تونیک؛ قدیمی‌ترین نسخه‌ی ثبت‌شده به ۲۰۰۷ در اسلو برمی‌گردد. ترتیب سنتی: تونیک یخی در لیوان و اسپرسو روی آن برای لایه‌لایه‌شدن.","s":[["Wikipedia — Espresso and tonic","https://en.wikipedia.org/wiki/Espresso_and_tonic"]]},{"en":"Mucilage","fa":"موسیلاژ (مخاط میوه)","cat":"bean","d":"لایه‌ی چسبناک بین پرگامنت و پالپ میوه‌ی قهوه. با تخمیر یا ساییدن مکانیکی برداشته می‌شود.","s":[["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"]]},{"en":"Parchment","fa":"پرگامنت","cat":"bean","d":"لایه‌ی سختی که پس از برداشتن پالپ دور دانه می‌ماند و زیر پوسته‌ی نقره‌ای است؛ هنگام پوست‌گیری (hulling) برداشته می‌شود.","s":[["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"]]},{"en":"Fermentation","fa":"تخمیر (در فرآوری)","cat":"bean","d":"در فرآوری شسته، میکروب‌ها پالپ باقی‌مانده را تجزیه می‌کنند و بعد شسته می‌شود. طبق منبع حدود ۱۲ تا ۳۶ ساعت طول می‌کشد و باید دقیق کنترل شود، چون زیاده‌روی قهوه را ترش می‌کند.","s":[["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"]]},{"en":"Hulling","fa":"پوست‌گیری","cat":"bean","d":"برداشتن مکانیکی لایه‌های خشک بیرونی (پرگامنت یا میوه‌ی خشک) تا دانه‌ی سبز بماند.","s":[["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"]]},{"en":"Selective Picking","fa":"برداشت انتخابی","cat":"farm","d":"فقط چیدن دانه‌های رسیده، یک‌به‌یک و با دست. چیننده‌ها هر ۸ تا ۱۰ روز برمی‌گردند؛ پرهزینه‌تر است و بیشتر برای عربیکای مرغوب به کار می‌رود.","s":[["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"]]},{"en":"Strip Picking","fa":"برداشت یک‌جا","cat":"farm","d":"برداشتن همه‌ی میوه‌ی درخت، چه رسیده چه نارس، با دست یا ماشین. سریع‌تر و ارزان‌تر است.","s":[["Wikipedia — Coffee production","https://en.wikipedia.org/wiki/Coffee_production"]]},{"en":"Slurping","fa":"سُرپ‌کردن","cat":"taste","d":"در کاپینگ، قهوه را با قاشق به‌صورت صدادار می‌مکند تا هوا بگیرد و روی زبان پخش شود.","s":[["Wikipedia — Coffee cupping","https://en.wikipedia.org/wiki/Coffee_cupping"]]},{"en":"Body","fa":"بدنه","cat":"taste","d":"ویژگی فیزیکی نوشیدنی است: حس دهانی کامل، قوی و خوشایند، در برابر نازک و آبکی.","s":[["Wikipedia — Coffee cupping","https://en.wikipedia.org/wiki/Coffee_cupping"]]},{"en":"Acidity","fa":"اسیدیته (ترشی خوشایند)","cat":"taste","d":"در کاپینگ طعمی پایه از محلول اسید آلی است. وقتی تیز و دلپذیر باشد مطلوب است و با ترشی ناخوشایندِ قهوه‌ی بیش‌ازحد تخمیرشده فرق دارد.","s":[["Wikipedia — Coffee cupping","https://en.wikipedia.org/wiki/Coffee_cupping"]]},{"en":"Sweetness","fa":"شیرینی (در کاپینگ)","cat":"taste","d":"طعمی پایه از محلول ساکارز یا فروکتوز. برای توصیف قهوه‌هایی به کار می‌رود که طعم‌های ناخوشایند ندارند.","s":[["Wikipedia — Coffee cupping","https://en.wikipedia.org/wiki/Coffee_cupping"]]},{"en":"Flavour","fa":"فلیور (طعم)","cat":"taste","d":"یعنی «ویژگی‌هایی که در فنجان هست».","s":[["Wikipedia — Coffee cupping","https://en.wikipedia.org/wiki/Coffee_cupping"]]},{"en":"Aroma","fa":"آروما (بو)","cat":"taste","d":"توصیف‌های آروما شامل میوه‌ای و مرکباتی، شکلاتی و خاکی است.","s":[["Wikipedia — Coffee cupping","https://en.wikipedia.org/wiki/Coffee_cupping"]]},{"en":"Drying Phase","fa":"فاز خشک‌شدن","cat":"roast","d":"در برشته‌کاری دانه گرما را جذب می‌کند (فرایند گرماگیر) تا رطوبتش تبخیر شود. به آن «فاز زردشدن» هم می‌گویند و حدود ۱۶۵ درجه‌ی سانتی‌گراد رخ می‌دهد.","s":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"en":"Roast Weight Loss","fa":"افت وزن برشته‌کاری","cat":"roast","d":"دانه‌ها در برشته‌کاری ۱۵ تا ۱۸٪ جرم خود را از دست می‌دهند، بیشتر از راه از دست رفتن آب و کمی هم ترکیبات فرار.","s":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"en":"Cinnamon / New England Roast","fa":"برشته‌ی دارچینی / نیوانگلند","cat":"roast","d":"از برشته‌های روشن: دارچینی حدود ۱۹۶ و نیوانگلند حدود ۲۰۵ درجه‌ی سانتی‌گراد. دانه سطحی خشک دارد، بدنه سبک‌تر و اسیدیته بیشتر و شخصیت منشأ در بیشترین حالت است.","s":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"en":"American / City Roast","fa":"برشته‌ی آمریکایی / سیتی","cat":"roast","d":"از برشته‌های متوسط: آمریکایی حدود ۲۱۰ و سیتی حدود ۲۱۹ درجه. دانه از کرک اول گذشته، اسیدیته ملایم‌تر و بدنه بیشتر است.","s":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"en":"Full City / French / Italian","fa":"فول‌سیتی / فرنچ / ایتالین","cat":"roast","d":"از برشته‌های تیره: فول‌سیتی حدود ۲۲۵ (آغاز کرک دوم)، فرنچ حدود ۲۴۰ (پایان کرک دوم، دانه‌ی تیره و براق و روغنی) و ایتالین حدود ۲۴۵ درجه (تقریباً سیاه، طعم سوخته و بدنه‌ی نازک). شخصیت منشأ بیشتر از دست می‌رود.","s":[["Wikipedia — Coffee roasting","https://en.wikipedia.org/wiki/Coffee_roasting"]]},{"en":"Defects","fa":"عیب‌ها (در گریدبندی)","cat":"market","d":"قهوه‌ی تخصصی طبق منبع در هر ۳۵۰ گرم دانه‌ی فرآوری‌شده بیش از پنج عیب ندارد.","s":[["Wikipedia — Specialty coffee","https://en.wikipedia.org/wiki/Specialty_coffee"]]},{"en":"Under-extraction","fa":"کم‌استخراجی","cat":"brew","d":"بازده کمتر از ۱۸٪ کم‌استخراج یا «کم‌توسعه» است و نوشیدنی معمولاً غالباً ترش می‌شود.","s":[["Wikipedia — Coffee extraction","https://en.wikipedia.org/wiki/Coffee_extraction"]]},{"en":"Extraction Yield","fa":"بازده استخراج","cat":"brew","d":"جرم منتقل‌شده از تفاله‌ی قهوه به آب، به‌صورت درصدی از جرم اولیه‌ی تفاله. به آن solubles yield هم می‌گویند. بازده بیش از ۲۲٪ بیش‌استخراج است و غالباً تلخ.","s":[["Wikipedia — Coffee extraction","https://en.wikipedia.org/wiki/Coffee_extraction"]]},{"en":"Strength","fa":"غلظت نوشیدنی","cat":"brew","d":"درصد مواد محلول در هر واحد از نوشیدنی نهایی (solubles concentration). محدوده‌ی معمول در آمریکای شمالی: بازده ۱۸ تا ۲۲٪ و غلظت ۱٫۱۵ تا ۱٫۳۵٪؛ در کشورهای شمال اروپا ۱٫۳۰ تا ۱٫۵۰٪ و در دیگر کشورهای اروپایی ۱٫۲۰ تا ۱٫۴۵٪.","s":[["Wikipedia — Coffee extraction","https://en.wikipedia.org/wiki/Coffee_extraction"]]},{"en":"Stepped vs Stepless Grinder","fa":"آسیاب پله‌ای و بی‌پله","cat":"gear","d":"آسیاب پله‌ای تنظیم‌های ثابتِ کارخانه‌ای دارد؛ آسیاب بی‌پله با مکانیزم حلزونی بی‌نهایت تنظیم در بازه‌ی خود می‌دهد. فاصله‌ی بیشتر بین برها یعنی آسیاب درشت‌تر.","s":[["Wikipedia — Coffee grinder","https://en.wikipedia.org/wiki/Coffee_grinder"]]},{"en":"Doser vs Doserless","fa":"آسیاب دوزری و بدون دوزر","cat":"gear","d":"آسیاب دوزری ساییده را در مخزنی جمع می‌کند و با اهرم مقدار ثابتی خارج می‌کند؛ مدل بدون دوزر مستقیم به پورتافیلتر یا ظرف می‌ریزد.","s":[["Wikipedia — Coffee grinder","https://en.wikipedia.org/wiki/Coffee_grinder"]]},{"en":"AeroPress","fa":"ایروپرس","cat":"gear","d":"ساخته‌ی آلن آدلر؛ نمونه‌سازی از ۲۰۰۴ و رونمایی نوامبر ۲۰۰۵ در نمایشگاه CoffeeFest سیاتل. قهوه در محفظه‌ی استوانه‌ای خیس می‌خورد و با پیستون به‌سمت فیلتر رانده می‌شود. دستور رسمی: آب حدود ۸۰ درجه برای برشته‌ی تیره و ۸۵ برای روشن، حدود ۱۰ ثانیه هم زدن و پرس.","s":[["Wikipedia — AeroPress","https://en.wikipedia.org/wiki/AeroPress"]]},{"en":"Inverted Method (AeroPress)","fa":"روش وارونه (ایروپرس)","cat":"brew","d":"پیستون اول داخل محفظه می‌رود و دستگاه وارونه روی آن می‌ایستد؛ قهوه و آب ریخته و هم زده می‌شود، فیلتر خیس در درپوش بسته می‌شود و پس از دم‌آوری دستگاه برمی‌گردد و پرس می‌شود. شبیه فرنچ‌پرس است و برای آسیاب درشت‌تر مناسب است.","s":[["Wikipedia — AeroPress","https://en.wikipedia.org/wiki/AeroPress"]]},{"en":"Chemex","fa":"کمکس","cat":"gear","d":"ساخته‌ی پیتر شلومبوم در ۱۹۴۱: فلاسک شیشه‌ای ساعت‌شنی با گردن قیفی و یقه‌ی چوبی. فیلترهایش از فیلتر معمول دریپ ضخیم‌ترند و در مجموعه‌ی موزه‌ی هنر مدرن (MoMA) نیویورک قرار دارد.","s":[["Wikipedia — Chemex Coffeemaker","https://en.wikipedia.org/wiki/Chemex_Coffeemaker"]]},{"en":"Siphon / Vacuum Pot","fa":"سیفون (وکیوم پات)","cat":"gear","d":"ساخته‌ی یوهان نورنبرگ در ۱۸۲۷. با گرم‌شدن ظرف پایینی، فشار بخار آب را از لوله به ظرف بالایی می‌راند و قهوه در حدود ۱۰۰ درجه خیس می‌خورد. با برداشتن حرارت، قهوه دوباره پایین می‌آید و تفاله در ظرف بالا می‌ماند.","s":[["Wikipedia — Vacuum coffee maker","https://en.wikipedia.org/wiki/Vacuum_coffee_maker"]]},{"en":"Free Pour vs Etching","fa":"فری‌پور و اچینگ","cat":"milk","d":"در فری‌پور طرح هنگام ریختن شیر شکل می‌گیرد؛ در اچینگ پس از ریختن، با چوب روی آن نقش می‌کشند.","s":[["Wikipedia — Latte art","https://en.wikipedia.org/wiki/Latte_art"]]},{"en":"Rosetta","fa":"روزتا","cat":"milk","d":"طرح پیچیده‌تر لاته‌آرت که در گریدهای بالاتر لازم است؛ قلب و لاله طرح‌های پایه‌اند. دیوید شومر آن را در ۱۹۹۲ از روی عکسی از Cafe Mateki ایتالیا ساخت.","s":[["Wikipedia — Latte art","https://en.wikipedia.org/wiki/Latte_art"]]},{"en":"LAGS","fa":"سیستم گریدبندی لاته‌آرت (LAGS)","cat":"milk","d":"سیستمی از لوئیجی لوپی و لوکا رامونی که مهارت را با امتحان عملی و رنگ می‌سنجد؛ ابتدا پنج درجه (سفید، نارنجی، سبز، قرمز، سیاه) و بعدها طلایی به‌عنوان درجه‌ی ششم.","s":[["Wikipedia — Latte art","https://en.wikipedia.org/wiki/Latte_art"]]},{"en":"Dialing In","fa":"دایل‌این (تنظیم شات)","cat":"esp","d":"تنظیم اندازه‌ی آسیاب، دوز و یلد تا قهوه با دستگاه و شرایط روز جور شود؛ توصیه می‌شود هر بار فقط یک متغیر عوض شود.","s":[["Talk About Coffee — Barista & Coffee Shop Glossary","https://www.talkaboutcoffee.com/barista-coffee-shop-glossary.html"],["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"]]},{"en":"Channeling","fa":"کانالینگ (مجراسازی)","cat":"esp","d":"مسیر کم‌مقاومت پیدا کردن آب در پاک؛ فقط بخشی از قهوه استخراج می‌شود و شات سریع، رقیق و ترش درمی‌آید. توزیع یکنواخت و تمپ درست جلویش را می‌گیرد.","s":[["Talk About Coffee — Barista & Coffee Shop Glossary","https://www.talkaboutcoffee.com/barista-coffee-shop-glossary.html"],["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"],["Complete Home Barista — Espresso Glossary","https://completehomebarista.com/guides/espresso-glossary/"]]},{"en":"Puck","fa":"پاک (قرص قهوه)","cat":"esp","d":"بستر فشرده‌ی قهوه در پورتافیلتر؛ پس از دم‌آوری «پاک مصرف‌شده» نام دارد.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"],["Talk About Coffee — Barista & Coffee Shop Glossary","https://www.talkaboutcoffee.com/barista-coffee-shop-glossary.html"]]},{"en":"Brew Time","fa":"زمان دم‌آوری (استخراج)","cat":"esp","d":"فاصله‌ی روشن‌شدن تا خاموش‌شدن پمپ. بازه‌ی امروزی قابل‌قبول ۲۵ تا ۴۵ ثانیه ذکر شده است.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Brew Temperature","fa":"دمای دم‌آوری","cat":"esp","d":"بازه‌ی دمای آبی که برای استخراج مناسب‌ترین شناخته می‌شود: حدود ۱۹۰ تا ۲۰۵ درجه‌ی فارنهایت (حدود ۸۸ تا ۹۶ درجه‌ی سانتی‌گراد) در سطح دریا.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Bar (Brewing Pressure)","fa":"بار (فشار دم‌آوری)","cat":"esp","d":"واحد فشار؛ حدود ۹ بار (حدود ۱۳۰ پی‌اس‌آی) فشار معمول دم‌آوری اسپرسو است. مؤسسه‌ی ملی اسپرسوی ایتالیا فشار ورودی آب را ۹ بار با تلورانس یک بار (از ۸ تا ۱۰ بار) تعیین کرده است.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"en":"Pre-infusion","fa":"پیش‌خیساندن","cat":"esp","d":"خیساندن بستر قهوه با فشار کم یا صفر پیش از فشار کامل تا پاک یکنواخت متورم شود و کانالینگ کم شود؛ روش اجرا در دستگاه‌ها فرق می‌کند.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Complete Home Barista — Espresso Glossary","https://completehomebarista.com/guides/espresso-glossary/"],["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"]]},{"en":"Pressure Profiling","fa":"پروفایل فشار","cat":"esp","d":"تغییر یا برنامه‌ریزی فشار در حین دم‌آوری. ماشین‌های اهرمی از ابتدا این کار را به‌صورت دستی ممکن می‌کردند.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Espresso Ratios (1:1.5 / 1:2 / 1:3)","fa":"نسبت‌های اسپرسو","cat":"esp","d":"نسبت دوز به یلد: ۱ به ۱٫۵ «نسبت ریسترتو»، ۱ به ۲ «نسبت طلایی» (مثلاً ۱۸ گرم قهوه و ۳۶ گرم اسپرسو) و ۱ به ۳ «نسبت ایتالیایی» نامیده می‌شود.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Naked Portafilter","fa":"پورتافیلتر لخت (بدون ته)","cat":"esp","d":"پورتافیلتری که کفِ توپر آن برداشته شده تا جریان شات دیده شود؛ باریستاها با آن کیفیت آسیاب، یکنواختی استخراج و کانالینگ را بررسی می‌کنند.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Wikipedia — Espresso machine","https://en.wikipedia.org/wiki/Espresso_machine"],["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"]]},{"en":"Coda di Topo","fa":"کودا دی توپو (دم موش)","cat":"esp","d":"«دم موش» به ایتالیایی؛ شکل جریان اسپرسو از نازل‌های پورتافیلتر که نشانه‌ی جریان یکنواخت است.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Tiger Striping","fa":"راه‌راه ببری","cat":"esp","d":"رگه‌های قهوه‌ای دیده‌شده در جریان اسپرسو که نشانه‌ی تکنیک خوب، تازگی و دمای مناسب شمرده می‌شود.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"God Shot","fa":"شات خدایی","cat":"slang","d":"بهترین شاتی که یک نفر تا به حال کشیده؛ هدفی متحرک که با پیشرفت مهارت جابه‌جا می‌شود.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Stall","fa":"استال (گیرکردن پمپ)","cat":"esp","d":"وقتی پمپ نمی‌تواند آب را از قهوه‌ی بسیار ریز یا سفت تمپ‌شده عبور دهد؛ بیشتر در ریسترتو پیش می‌آید.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Portafilter Sneeze","fa":"عطسه‌ی پورتافیلتر","cat":"slang","d":"پاشیدن قهوه‌ی داغ و خیس هنگام برداشتن پورتافیلتر پیش از آنکه فشار آن تخلیه شود.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Pressurized Portafilter","fa":"پورتافیلتر فشاری","cat":"esp","d":"پورتافیلتری با سوراخ ریز داخلی برای افزایش کرما؛ در مدل‌های معمولی با سبد معمولی کار می‌کند. سبد فشاری هم همین ایده را دارد و کرمای مصنوعی می‌سازد.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Complete Home Barista — Espresso Glossary","https://completehomebarista.com/guides/espresso-glossary/"]]},{"en":"Blind Basket","fa":"سبد کور","cat":"esp","d":"سبد توپر و بدون سوراخ که برای بک‌فلاش (و تمیز کردن آسیاب) به‌کار می‌رود.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Visions Espresso — Visions Vocabulary","https://visionsespresso.com/visions-vocab/"]]},{"en":"Basket","fa":"سبد پورتافیلتر","cat":"esp","d":"درج فلزی سوراخ‌دار پورتافیلتر که بستر قهوه را نگه می‌دارد؛ در اندازه‌های تک، دبل و تریپل. رایج‌ترین سبد، دبل است با حدود ۱۴ گرم قهوه یا بیشتر.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Talk About Coffee — Barista & Coffee Shop Glossary","https://www.talkaboutcoffee.com/barista-coffee-shop-glossary.html"]]},{"en":"Backflush","fa":"بک‌فلاش","cat":"esp","d":"شست‌وشوی گروه‌هد و سامانه‌ی آزادسازی فشار با راندن آب از میان سبد کور تا باقی‌مانده‌ی قهوه خارج شود؛ گاهی با مواد شوینده.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Visions Espresso — Visions Vocabulary","https://visionsespresso.com/visions-vocab/"],["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"]]},{"en":"Descale","fa":"رسوب‌زدایی","cat":"gear","d":"زدودن رسوب معدنی از دیگ بخار و مسیر آب؛ با تمیزکاری که روغن‌ها را می‌زداید فرق دارد و هر دو لازم‌اند.","s":[["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"]]},{"en":"Purge","fa":"پرج (تخلیه)","cat":"esp","d":"فوران بخار از وند برای پاک‌کردن آب یا شیر، یا آسیاب‌کردن و دورریختن مقداری قهوه برای خالی‌کردن آسیاب.","s":[["Visions Espresso — Visions Vocabulary","https://visionsespresso.com/visions-vocab/"]]},{"en":"Distribution","fa":"توزیع قهوه","cat":"esp","d":"یکنواخت‌کردن قهوه‌ی آسیاب‌شده در سبد پیش از تمپ تا آب با مقاومت یکسان روبه‌رو شود. ابزار توزیع (دیستریبیوتور) برای تراز کردن بستر قهوه به‌کار می‌رود.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Talk About Coffee — Barista & Coffee Shop Glossary","https://www.talkaboutcoffee.com/barista-coffee-shop-glossary.html"],["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"]]},{"en":"WDT (Weiss Distribution Technique)","fa":"دبلیو‌دی‌تی (تکنیک توزیع وایس)","cat":"esp","d":"هم‌زدن بستر قهوه با سوزن‌های نازک پیش از تمپ تا کلوخه‌ها باز شوند؛ ابزاری ارزان و مؤثر در برابر کانالینگ.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Visions Espresso — Visions Vocabulary","https://visionsespresso.com/visions-vocab/"],["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"],["Complete Home Barista — Espresso Glossary","https://completehomebarista.com/guides/espresso-glossary/"]]},{"en":"Knock Box","fa":"ناک‌باکس","cat":"esp","d":"سطل مخصوص با میله‌ای روی دهانه‌اش که پاک مصرف‌شده را با ضربه‌ی پورتافیلتر در آن خالی می‌کنند.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Visions Espresso — Visions Vocabulary","https://visionsespresso.com/visions-vocab/"],["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"]]},{"en":"Demitasse","fa":"دمی‌تاس (فنجان اسپرسو)","cat":"serve","d":"فنجان کوچک (حدود ۳ اونس یا کمتر) برای اسپرسو؛ فنجان‌های ضخیم‌تر گرما را بهتر نگه می‌دارند.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Gasket","fa":"واشر (گسکت)","cat":"gear","d":"اصطلاح کلی برای اورینگ‌ها و آب‌بندها از جمله آب‌بند گروه‌هد؛ بیش از همه تعویض‌شونده در گروه‌هد.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Visions Espresso — Visions Vocabulary","https://visionsespresso.com/visions-vocab/"]]},{"en":"Dispersion Screen","fa":"صافی پخش‌کننده (شاور اسکرین)","cat":"gear","d":"قطعه‌ای در بخش گروه که آب را روی بستر قهوه به‌طور یکنواخت پخش می‌کند.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Wikipedia — Espresso machine","https://en.wikipedia.org/wiki/Espresso_machine"]]},{"en":"Pressure Relief System (3-Way Solenoid)","fa":"سامانه‌ی آزادسازی فشار (شیر سه‌راهه)","cat":"gear","d":"شیر سه‌راهه‌ای که پس از دم‌آوری فشار را از پورتافیلتر خارج می‌کند.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Recovery Time","fa":"زمان بازیابی","cat":"gear","d":"فاصله‌ی انتظار بین شات‌های پیاپی تا دستگاه دوباره آماده شود؛ با دیگ‌های بزرگ‌تر یا هیت‌اکسچنجر کوتاه‌تر است.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Temperature Stability","fa":"پایداری دما","cat":"gear","d":"ثبات دما از دیگ تا گروه‌هد، به‌ویژه بین شات‌های پیاپی.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Temperature Surfing","fa":"موج‌سواری دمایی","cat":"slang","d":"زمان‌بندی شات‌ها در چرخه‌ی گرمایش یک دستگاه تک‌دیگ، یا خنک‌کردن کوتاه دیگ، برای رسیدن به دمای هدف.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Heat Exchanger (HX)","fa":"هیت‌اکسچنجر","cat":"gear","d":"دیگی که در دمای بخار نگه داشته می‌شود و آب دم‌آوری از یک مبدل حرارتی در آن می‌گذرد و خنک می‌شود؛ پیش از اولین شات به فلاش خنک‌کننده‌ی ۴ تا ۶ ثانیه‌ای نیاز دارد. در دستگاه‌های میان‌رده رایج است.","s":[["Wikipedia — Espresso machine","https://en.wikipedia.org/wiki/Espresso_machine"],["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Dual Boiler","fa":"دوال‌بویلر (دو دیگ)","cat":"gear","d":"آب دم‌آوری در دیگی جدا گرم می‌شود و دستگاه دو دیگ دارد؛ بیشتر در مدل‌های گران‌تر. نخستین نمونه، لامارزوکو GS در سال ۱۹۷۰ بود.","s":[["Wikipedia — Espresso machine","https://en.wikipedia.org/wiki/Espresso_machine"]]},{"en":"Thermoblock","fa":"ترموبلاک","cat":"gear","d":"سامانه‌ی گرمایش با کانال‌ها یا سیم‌پیچ‌های فلزی که آب هنگام عبور داغ‌تر می‌شود. راه‌اندازی سریعی دارد ولی زیر بار کم‌پایدارتر است.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Wikipedia — Espresso machine","https://en.wikipedia.org/wiki/Espresso_machine"],["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"]]},{"en":"E61 Group","fa":"گروه ای‌۶۱","cat":"gear","d":"طراحی رایج گروه‌هد که با آب کشیده‌شده از دیگ گرم می‌شود و به پایداری دما کمک می‌کند. فائما E61 در ۱۹۶۱ معرفی شد و نخستین طراحی پمپی و هیت‌اکسچنجر بود.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Wikipedia — Espresso machine","https://en.wikipedia.org/wiki/Espresso_machine"]]},{"en":"PID","fa":"پی‌آی‌دی","cat":"gear","d":"کنترل‌گر دقیق دما که آب دم‌آوری را در بازه‌ای باریک نگه می‌دارد، به‌جای نوسان ترموستات؛ حدود سال ۲۰۰۰ وارد اسپرسوی خانگی شد.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"]]},{"en":"Rotary vs Vibratory Pump","fa":"پمپ روتاری و ویبراتوری","cat":"gear","d":"پمپ‌ها حدود ۱۳۵ پی‌اس‌آی فشار می‌دهند. پمپ ویبراتوری (دیافراگمی) در دستگاه‌های خانگی رایج است و از مخزن می‌کشد؛ روتاری (حجمی/پروکان) تجاری است و به آب لوله‌کشی نیاز دارد.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Lever Machine","fa":"دستگاه اهرمی","cat":"gear","d":"ماشینی که آشیل گاجیا در ۱۹۴۵ در ایتالیا ساخت: اپراتور با اهرم فشار می‌دهد. دو نوع دارد: پیستون دستی که نیروی دست مستقیم آب را می‌راند و پیستون فنری که فنر فشار (معمولاً ۸ تا ۱۰ بار) را تأمین می‌کند.","s":[["Wikipedia — Espresso machine","https://en.wikipedia.org/wiki/Espresso_machine"],["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Semi-Auto vs Super Automatic","fa":"نیمه‌خودکار و تمام‌خودکار","cat":"gear","d":"در نیمه‌خودکار دستگاه فشار و دما را کنترل می‌کند ولی زمان دم‌آوری با اپراتور است؛ در تمام‌خودکار دستگاه با یک دکمه آسیاب، دوز، تمپ، دم‌آوری و تخلیه‌ی پاک را انجام می‌دهد.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Prosumer","fa":"پروزیومر","cat":"gear","d":"دستگاه‌هایی با مصالح یا ویژگی‌های سبک تجاری که ممکن است برای کاربری تجاری سبک هم به‌کار روند.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Retention","fa":"ماندگاری (رتنشن)","cat":"gear","d":"قهوه‌ی آسیاب‌شده‌ای که پس از آسیاب در مسیر خروجی یا بین تیغه‌ها در آسیاب می‌ماند و می‌تواند بر یکنواختی اثر بگذارد.","s":[["Visions Espresso — Visions Vocabulary","https://visionsespresso.com/visions-vocab/"]]},{"en":"Boulders","fa":"بولدر (ذرات درشت)","cat":"gear","d":"ذرات بیش‌ازحد درشت آسیاب‌شده؛ در برابر فاین‌ها که ذرات بسیار ریزند.","s":[["Visions Espresso — Visions Vocabulary","https://visionsespresso.com/visions-vocab/"]]},{"en":"Conical vs Flat Burrs","fa":"تیغه‌ی مخروطی و تخت","cat":"gear","d":"تیغه‌ی مخروطی (یک مخروط و یک حلقه، یکی ثابت و دیگری چرخان) آسیاب دومدی می‌سازد؛ تیغه‌ی تخت (دو دیسک) آسیابی یکنواخت‌تر با فاین و بولدر کمتر.","s":[["Visions Espresso — Visions Vocabulary","https://visionsespresso.com/visions-vocab/"]]},{"en":"Grind by Weight (GbW)","fa":"آسیاب بر مبنای وزن","cat":"gear","d":"ترازوی داخلی آسیاب اجازه می‌دهد مقدار مشخصی را بر حسب وزن آسیاب کنید؛ دقیق‌تر از آسیاب بر مبنای زمان.","s":[["Visions Espresso — Visions Vocabulary","https://visionsespresso.com/visions-vocab/"]]},{"en":"Clumping","fa":"کلوخه‌شدن","cat":"gear","d":"به‌هم‌چسبیدن ذرات آسیاب‌شده که اغلب از الکتریسیته‌ی ساکن یا تنظیم نامناسب است و نشانه‌ی نیاز به تمیزکاری یا آسیاب درشت‌تر.","s":[["Visions Espresso — Visions Vocabulary","https://visionsespresso.com/visions-vocab/"]]},{"en":"Gooseneck Kettle","fa":"کتری گردن‌غازی","cat":"gear","d":"کتری با نوک خمیده‌ی باریک برای ریختن آهسته و هدفمند آب.","s":[["Visions Espresso — Visions Vocabulary","https://visionsespresso.com/visions-vocab/"],["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"]]},{"en":"Hopper","fa":"مخزن دانه (هاپر)","cat":"gear","d":"بخش بالای آسیاب که دانه‌ی کامل را نگه می‌دارد.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"],["Talk About Coffee — Barista & Coffee Shop Glossary","https://www.talkaboutcoffee.com/barista-coffee-shop-glossary.html"]]},{"en":"Percolation","fa":"پرکولیشن (عبور آب)","cat":"brew","d":"عبور آب از بستر قهوه و تخلیه‌ی آن، مثل دم‌آوری قطره‌ای و پورآور؛ در برابر ایمرشن.","s":[["Visions Espresso — Visions Vocabulary","https://visionsespresso.com/visions-vocab/"],["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"]]},{"en":"Bypass Water","fa":"آب بای‌پس","cat":"brew","d":"آبی که پس از دم‌آوری برای تنظیم غلظت اضافه می‌شود، مثل آمریکانو.","s":[["Visions Espresso — Visions Vocabulary","https://visionsespresso.com/visions-vocab/"]]},{"en":"Nitro Cold Brew","fa":"نایترو کلدبرو","cat":"serve","d":"کلدبرو که با نیتروژن آمیخته شده و بدون لبنیات، ریزش آبشاری و بافتی خامه‌ای می‌دهد.","s":[["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"]]},{"en":"Stretching & Texturing","fa":"استرچینگ و تکسچرینگ","cat":"milk","d":"استرچینگ مرحله‌ی اول بخاردهی است که هوا اضافه می‌کند تا حجم شیر زیاد شود؛ تکسچرینگ چرخاندن شیر برای شکستن حباب‌های درشت و رسیدن به میکروفوم است.","s":[["Talk About Coffee — Barista & Coffee Shop Glossary","https://www.talkaboutcoffee.com/barista-coffee-shop-glossary.html"]]},{"en":"Frothing Pitcher","fa":"پیچر (جگ شیر)","cat":"milk","d":"پیچر استیل برای بخاردهی و کف‌دادن شیر؛ اغلب «پیچر بخاردهی» نامیده می‌شود.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Frothing Tip","fa":"نوک کف‌ساز","cat":"milk","d":"نوک سوراخ‌دار وند بخار که بخار را به‌صورت فواره درمی‌آورد تا شیر را گرم و هواده کند.","s":[["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Heart & Tulip","fa":"هارت و تولیپ","cat":"milk","d":"دو طرح ساده‌ی لاته‌آرت. هارت تا ۱۹۸۹ به امضای اسپرسو ویواچه‌ی دیوید شومر تبدیل شده بود؛ در سطوح پایین‌تر LAGS از داوطلب انتظار می‌رود هر دو را بسازد.","s":[["Wikipedia — Latte art","https://en.wikipedia.org/wiki/Latte_art"]]},{"en":"Wet vs Dry (Cappuccino)","fa":"خیس و خشک (کاپوچینو)","cat":"slang","d":"در سفارش کاپوچینو «خشک» یعنی کف بیشتر و «خیس» یعنی شیر بخارداده‌ی بیشتر.","s":[["Talk About Coffee — Barista & Coffee Shop Glossary","https://www.talkaboutcoffee.com/barista-coffee-shop-glossary.html"]]},{"en":"For Here vs To Go","fa":"داخل یا بیرون‌بر","cat":"slang","d":"فنجان سرامیکی برای نوشیدن در کافه، یا لیوان کاغذی دردار برای بیرون‌بر.","s":[["Talk About Coffee — Barista & Coffee Shop Glossary","https://www.talkaboutcoffee.com/barista-coffee-shop-glossary.html"]]},{"en":"Blonde","fa":"بلوند","cat":"slang","d":"درخواست برشته‌ی بسیار روشن.","s":[["Talk About Coffee — Barista & Coffee Shop Glossary","https://www.talkaboutcoffee.com/barista-coffee-shop-glossary.html"]]},{"en":"Red Eye","fa":"ردآی","cat":"serve","d":"قهوه‌ی دمی معمولی (گرم یا سرد) به‌اضافه‌ی شات اسپرسو برای شدت طعم یا کافئین بیشتر؛ گاهی «شات در تاریکی» (shot in the dark) هم گفته می‌شود.","s":[["Compass Coffee — A Coffee Glossary","https://shop.compasscoffee.com/blogs/the-daily-grind/a-coffee-glossary"],["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"en":"Black Eye & Dead Eye","fa":"بلک‌آی و ددآی","cat":"slang","d":"در استارباکس، اضافه‌کردن دبل‌شات (بلک‌آی) یا تریپل‌شات (ددآی) اسپرسو به قهوه.","s":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"en":"Breve","fa":"برو","cat":"serve","d":"اسپرسو با نیمه‌شیر و نیمه‌خامه‌ی (half and half) بخارداده؛ غنی‌تر و سنگین‌تر.","s":[["Barista Life — Coffee Glossary","https://baristalife.co/pages/coffee-glossary"]]},{"en":"Caffè Corretto","fa":"کافه کورِتو","cat":"serve","d":"یک شات اسپرسو که با یک شات مشروب، معمولاً گراپا، براندی یا سامبوکا «اصلاح» شده است.","s":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"en":"Con Panna","fa":"کون پانا","cat":"serve","d":"اسپرسو با خامه.","s":[["Wikipedia — Espresso","https://en.wikipedia.org/wiki/Espresso"]]},{"en":"Café Bombón","fa":"کافه بومبون","cat":"serve","d":"اسپرسو با شیر تغلیظ‌شده‌ی شیرین (کندانسه) به نسبت ۱ به ۱؛ در والنسیای اسپانیا محبوب شد.","s":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"en":"Caffè Mocha","fa":"موکا","cat":"serve","d":"نوعی کافه لاته که حدود یک‌سوم اسپرسو و دوسوم شیر بخارداده دارد و شکلات (معمولاً شربت) به آن اضافه می‌شود.","s":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"],["Compass Coffee — A Coffee Glossary","https://shop.compasscoffee.com/blogs/the-daily-grind/a-coffee-glossary"],["CoffeeGeek — An Espresso Glossary","https://www.coffeegeek.com/opinions/an-espresso-glossary/"]]},{"en":"Greek Frappé","fa":"فراپه‌ی یونانی","cat":"serve","d":"قهوه‌ی سرد کفی از قهوه‌ی فوری اسپری‌خشک؛ در یونان به‌ویژه تابستان‌ها بسیار محبوب است.","s":[["Wikipedia — List of coffee drinks","https://en.wikipedia.org/wiki/List_of_coffee_drinks"]]},{"en":"Liberica","fa":"لیبریکا","cat":"bean","d":"گونه‌ای با کشت بسیار اندک؛ طعمی پررنگ، دودی، چوبی و آجیلی دارد، هرچند مزه‌ی سوخته‌اش برخی را خوش نمی‌آید. اغلب با دانه‌های دیگر ترکیب می‌شود.","s":[["Lavazza — Barista Vocabulary","https://www.lavazza.com.au/en/coffee-secrets/barista-vocabulary-coffee-terms"]]},{"en":"Cascara","fa":"کاسکارا","cat":"bean","d":"پوست خشک‌شده‌ی گیلاس قهوه که برای دم‌کردن نوشیدنی‌های چای‌مانند مثل قِشر یمنی به‌کار می‌رود.","s":[["Compass Coffee — A Coffee Glossary","https://shop.compasscoffee.com/blogs/the-daily-grind/a-coffee-glossary"]]},{"en":"Balanced","fa":"متعادل","cat":"taste","d":"فنجانی که هیچ طعمی بر دیگران غالب نیست؛ نرم و یکدست ولی جالب.","s":[["Compass Coffee — A Coffee Glossary","https://shop.compasscoffee.com/blogs/the-daily-grind/a-coffee-glossary"]]},{"en":"Complexity","fa":"پیچیدگی","cat":"taste","d":"عمق طعم که هنگام عبور از کام چند حس پیاپی می‌سازد.","s":[["Compass Coffee — A Coffee Glossary","https://shop.compasscoffee.com/blogs/the-daily-grind/a-coffee-glossary"]]},{"en":"Bold","fa":"بولد (پرقدرت)","cat":"taste","d":"شدت طعم؛ با «قدرت» (strength) یکی نیست: قدرت به نسبت آب به قهوه بستگی دارد و بولدبودن از دانه می‌آید.","s":[["Compass Coffee — A Coffee Glossary","https://shop.compasscoffee.com/blogs/the-daily-grind/a-coffee-glossary"]]}];
